var e=JSON.parse(`[{"id":"v_dc6e8686","type":"vote","entryId":"3b7643da","votedBelt":"Blue","comment":"Red Wanderer - Mine was mastered I think, and pretty easy bitting. No false gates of any sort. I only rank it above something like a zarker because of the number of discs and some slight difficulty getting the tensioner in the right spot.","userId":"XoUDXU5McjTuVnPA1xfmzytcKuy2","displayName":"Red Wanderer","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.317Z","updatedAt":"2026-10-09T16:10:57.317Z"},{"id":"v_c5447115","type":"vote","entryId":"3b7643da","votedBelt":"Green","comment":"LockPickingFisherman\\nFeedback is very clear. Spinner profile might require some lite modification to a DD tool. Front tensioned. My lock has 8 discs but 6 of them are zeros. The two discs I had to turn feel like they have false gates. True gates have a lot of play and are obvious. Even with 5 or six non-zeros, I can't see this being harder than green. I really want to vote orange but with so many zeros, I'm hesitant. I'd love to pick one with fewer zeros, if anyone is willing to send one my way, I'll send it back afterward.","userId":"IzvfeUBxzWcd8VXKHq0T4MUhtQu1","displayName":"LockPickingFisherman","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.317Z","updatedAt":"2026-10-09T16:11:57.317Z"},{"id":"v_5b226107","type":"vote","entryId":"18ecc45b","votedBelt":"Yellow","comment":"Red Wanderer - 4 pins, spools, restrictive keyway.\\n","userId":"XoUDXU5McjTuVnPA1xfmzytcKuy2","displayName":"Red Wanderer","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.319Z","updatedAt":"2026-10-09T16:10:57.319Z"},{"id":"v_3e31df8b","type":"vote","entryId":"18ecc45b","votedBelt":"Orange","comment":"Yagias: 5 pin core with 4 spools and 1 control.\\nCertainly harder that the Master Lock 140 and on par with an Abus 65 series","userId":"u_89015b15","displayName":"Yagias","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.319Z","updatedAt":"2026-10-09T16:11:57.319Z"},{"id":"v_84f44084","type":"vote","entryId":"18ecc45b","votedBelt":"Yellow","comment":"Explosion - 4 pins, spools, restrictive keyway, but very easy to set pins","userId":"XFUUNfloCTSBbNREKPDZNSRxPdq2","displayName":"Explosion","source":"Classification Sheet","createdAt":"2026-10-09T16:12:57.319Z","updatedAt":"2026-10-09T16:12:57.319Z"},{"id":"v_3d9ba0e7","type":"vote","entryId":"18ecc45b","votedBelt":"Orange","comment":"Same as many other ABUS with 4 spools and 1 regular on orange","userId":"u_12cc47d1","displayName":"Unknown","source":"Classification Sheet","createdAt":"2026-10-09T16:13:57.319Z","updatedAt":"2026-10-09T16:13:57.319Z"},{"id":"v_f8d58023","type":"vote","entryId":"fdc8b16e","votedBelt":"Yellow","comment":"Red Wanderer - picked 3 of these. Felt like serrated pins, but navigating the tiny yale keyway even with a short hook is annoying and leads to oversets. ","userId":"XoUDXU5McjTuVnPA1xfmzytcKuy2","displayName":"Red Wanderer","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.319Z","updatedAt":"2026-10-09T16:10:57.319Z"},{"id":"v_5d595415","type":"vote","entryId":"e98dba45","votedBelt":"Purple","comment":"Hard to find some feeling at first and need a LOT of tension to open, spent 5m rechecking every discs but it was already open\\nClef","userId":"tbaq0CWuDTXerA0eUi0kGASVb1Z2","displayName":"Clefmentine","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.319Z","updatedAt":"2026-10-09T16:10:57.319Z"},{"id":"v_a1cd7164","type":"vote","entryId":"1050a58c","votedBelt":"Orange","comment":"Very Similar to ABUS C83 with old pinning.\\nLockfumbler","userId":"gWoqbd0FOsglFD5boH96NAtJ7DE3","displayName":"LockFumbler","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.319Z","updatedAt":"2026-10-09T16:10:57.319Z"},{"id":"v_d1921247","type":"vote","entryId":"8182fee6","votedBelt":"Blue","comment":"Please see here for first pick https://www.youtube.com/watch?v=eKcA-ssqm0I\\n- GravityKarma","userId":"8PKfUHTiafgObsQQr162dQRlBCo1","displayName":"GravityKarma","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.319Z","updatedAt":"2026-10-09T16:10:57.319Z"},{"id":"v_94bc2c8e","type":"vote","entryId":"8182fee6","votedBelt":"Blue","comment":"This is similar to Bravus 1000 without the element, also similar to XD25. \\nSame as EC880. - decoder","userId":"Mwbvdkq1QtWu2zLwEaj3imULSry1","displayName":"decoder","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.319Z","updatedAt":"2026-10-09T16:11:57.319Z"},{"id":"v_26f6d45f","type":"vote","entryId":"c24808aa","votedBelt":"White","comment":"NiXXeD\\n3 pins, one tap each.","userId":"WMSvvuutyShfvBBYB3PmDe4fmeS2","displayName":"NiXXeD","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.319Z","updatedAt":"2026-10-09T16:10:57.319Z"},{"id":"v_8d9a5a02","type":"vote","entryId":"b370e57b","votedBelt":"Green","comment":"Peace: green but would require 350º pick, to pick the special pin. Else, don't think it's more than orange.","userId":"mZyfQIARjCP1uJJJc7ioMAALV9v2","displayName":"PeaceWeapon","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.320Z","updatedAt":"2026-10-09T16:10:57.320Z"},{"id":"v_e2cb1f9c","type":"vote","entryId":"b370e57b","votedBelt":"Green","comment":"Same as bravus 1000 with different key tip, should be same rating with 360° requirement","userId":"u_613272ae","displayName":"Unknown","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.320Z","updatedAt":"2026-10-09T16:11:57.320Z"},{"id":"v_070b6a11","type":"vote","entryId":"9ae8b650","votedBelt":"Purple","comment":"Iona\\nnot too hard but weird (wafers that act like discs, but you can pick with a hook), kinda like fontaine and others for ranking\\ncould be blue\\n","userId":"u_dded11a8","displayName":"Iona","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.378Z","updatedAt":"2026-10-09T16:10:57.378Z"},{"id":"v_41b43433","type":"vote","entryId":"9ae8b650","votedBelt":"Orange","comment":"Lock Noob\\neasy bitting\\nhttps://discord.com/channels/140129091796992000/349621948713795594/1108796783242518588","userId":"u_c940f29e","displayName":"Lock Noob","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.378Z","updatedAt":"2026-10-09T16:11:57.378Z"},{"id":"v_843ea334","type":"vote","entryId":"9ae8b650","votedBelt":"Green","comment":"Unusual but not actually hard.\\ncrispix","userId":"bSkotjOGENXHGd3rpo8G3TJeCk33","displayName":"Crispix","source":"Classification Sheet","createdAt":"2026-10-09T16:12:57.378Z","updatedAt":"2026-10-09T16:12:57.378Z"},{"id":"v_d56ae66e","type":"vote","entryId":"9ae8b650","votedBelt":"Orange","comment":"The plastic abloy Ava padlock. Flat and half round keyway version. Picked both. Both pick about the same. Half round is minimal more difficult to tension and picks slightly different due to round shape in the wafer. But that changes just pick placement. Front tension, just push the binding wafer and the core will turn with each wafer further. Pretty easy to open. Below the difficulty of spools I say even if unusual design. Orange or low green… it hurts, but I go with orange.\\n~Dig 05.03.2025","userId":"U3wCYsdGwYS8ujsO2K78iD68FMC3","displayName":"Dig","source":"Classification Sheet","createdAt":"2026-10-09T16:13:57.378Z","updatedAt":"2026-10-09T16:13:57.378Z"},{"id":"v_bf2224ff","type":"vote","entryId":"9ae8b650","votedBelt":"Orange","comment":"LockChuck - Not a hard pick. Just pushing the wafers from side to side until open. \\n","userId":"BuX3JAgrlzUW6Vz0L4W3YZK9iNw1","displayName":"LockChuck ","source":"Classification Sheet","createdAt":"2026-10-09T16:14:57.378Z","updatedAt":"2026-10-09T16:14:57.378Z"},{"id":"v_1a1f12e3","type":"vote","entryId":"9ae8b650","votedBelt":"Orange","comment":"Wiggle wafers until it opens.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T16:15:57.378Z","updatedAt":"2026-10-09T16:15:57.378Z"},{"id":"v_05061a6a","type":"vote","entryId":"8ce37fa9","votedBelt":"White","comment":"Really easy. Reasonable tension. Picked it with windshield wiper insert & Z-bar. — Marson","userId":"e2RNiz570rWqYYxDSDn6Y0uhgA43","displayName":"Marson","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.378Z","updatedAt":"2026-10-09T16:10:57.378Z"},{"id":"v_11cb31cb","type":"vote","entryId":"d95d6c74","votedBelt":"White","comment":"I used a 2-in-1, but could tell it was similar to the small one. — Marson","userId":"e2RNiz570rWqYYxDSDn6Y0uhgA43","displayName":"Marson","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.378Z","updatedAt":"2026-10-09T16:10:57.378Z"},{"id":"v_79e1bd7f","type":"vote","entryId":"343d6402","votedBelt":"Blue","comment":"11 Pins (6 top, 5 bottom).  Requires rear tension and that is the only real challenge.  All standard drivers that are fairly easy to set.  Only voting blue because tensioning is a little awkward.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.378Z","updatedAt":"2026-10-09T16:10:57.378Z"},{"id":"v_6f8202af","type":"vote","entryId":"343d6402","votedBelt":"Blue","comment":"A rear tensioned 2 row pin tumbler lock. It sounds weird but is actually pretty straightforward, the challenge is setting up an suitable tension setup that does rear tension and gives good access to both rows of pins. All pins are standard without quirks, blue seems fine\\n-Dynamic","userId":"vOi8rfTRluYlcVizuVvX9PWFJdn2","displayName":"Dynamic","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.378Z","updatedAt":"2026-10-09T16:11:57.378Z"},{"id":"v_24e0bb0b","type":"vote","entryId":"5288be2f","votedBelt":"Brown","comment":"17 pins in 3 rows.  Bottom pin is just a key control pin of sorts that just needs pushed all the way down.  Decent feedback, somewhat easy to overset when keyway is cramped with low lifts.  All standard drivers, not very tapered.  Straightforward, just a lot of pins.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.379Z","updatedAt":"2026-10-09T16:10:57.379Z"},{"id":"v_a82daaed","type":"vote","entryId":"02788bde","votedBelt":"Purple","comment":"13 pins.  Thin-lipped spools bite pretty hard.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.379Z","updatedAt":"2026-10-09T16:10:57.379Z"},{"id":"v_71b9eefe","type":"vote","entryId":"d5080254","votedBelt":"Purple","comment":"Yagias:\\nI'd recommend same lining with Gege pExtra as it's the same lock with a different brand. ","userId":"u_89015b15","displayName":"Yagias","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.379Z","updatedAt":"2026-10-09T16:10:57.379Z"},{"id":"v_afcc7b69","type":"vote","entryId":"4cd726f7","votedBelt":"Blue","comment":"6 sets of wafers (2 in a set that set together).  Leaves a lot to be desired.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.379Z","updatedAt":"2026-10-09T16:10:57.379Z"},{"id":"v_ea76c845","type":"vote","entryId":"4cd726f7","votedBelt":"Green","comment":"Jim\\n6 pairs of wafers in dual rows. One top, middle and bottom on each side. Picks like standard pins but can overset. I only needed to pick 4 of the 6 wafers to open and several gave huge core shifts letting you know you were on the right track. ","userId":"UbhgAjZIuLauV1dw2G4QsocHIk83","displayName":"Georgia Jim","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.379Z","updatedAt":"2026-10-09T16:11:57.379Z"},{"id":"v_30e6d9c1","type":"vote","entryId":"d60750c5","votedBelt":"Green","comment":"Jim\\nSame aptc14 core found in the 6 pin 1100’s","userId":"UbhgAjZIuLauV1dw2G4QsocHIk83","displayName":"Georgia Jim","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.379Z","updatedAt":"2026-10-09T16:10:57.379Z"},{"id":"v_b9dcec35","type":"vote","entryId":"88d5c4b4","votedBelt":"Orange","comment":"6 pins with gin type drivers without milling that basically do nothing.  \\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.379Z","updatedAt":"2026-10-09T16:10:57.379Z"},{"id":"v_3766e87c","type":"vote","entryId":"88d5c4b4","votedBelt":"Orange","comment":"Zehkar","userId":"1SqcRKce18boUZBtOHWSenGAI202","displayName":"Zehkar","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.379Z","updatedAt":"2026-10-09T16:11:57.379Z"},{"id":"v_762a3fa3","type":"vote","entryId":"c2db34fb","votedBelt":"Black 1","userId":"u_68bed142","displayName":"Unknown","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.379Z","updatedAt":"2026-10-09T16:10:57.379Z"},{"id":"v_96327680","type":"vote","entryId":"fd93632b","votedBelt":"Purple","comment":"Picks just like serrated mtl but with more muted feedback and serrations are less sharp. MGsec","userId":"GGplAdctTfVDLVvYsfIADJmfp8f2","displayName":"mgsecure","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.379Z","updatedAt":"2026-10-09T16:10:57.379Z"},{"id":"v_95fe121b","type":"vote","entryId":"e2fd1519","votedBelt":"Green","comment":"Tensioning from a disc in the middle, probably random. No false gates, muddy feedback. Tolerances aren't too good, which makes it a relatively easy pick - Greenish ","userId":"NdkmYGydSHfPTcj5xuqjwSyJJI42","displayName":"Greenish","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.380Z","updatedAt":"2026-10-09T16:10:57.380Z"},{"id":"v_fc0589b4","type":"vote","entryId":"e2fd1519","votedBelt":"Green","comment":"Seven discs and mid tension, no false gates, steady\\ncrispix","userId":"bSkotjOGENXHGd3rpo8G3TJeCk33","displayName":"Crispix","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.380Z","updatedAt":"2026-10-09T16:11:57.380Z"},{"id":"v_979317e3","type":"vote","entryId":"b68b677c","votedBelt":"Yellow","comment":"Simple little 5 pin lock that is easy to obtain in the states for sure. Think its a tad more challenging than the standard master locks, but nothing to brag about.  CajunLockPick\\n","userId":"u_fef23d37","displayName":"CajunLockPick","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.380Z","updatedAt":"2026-10-09T16:10:57.380Z"},{"id":"v_1b52a7a2","type":"vote","entryId":"2a69b223","votedBelt":"Green","comment":"low green, side element doesn't come into play.\\n\\n-rein ","userId":"f2yySWbxUBXF8k3HgorYhrm76gx2","displayName":"Reinder","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.381Z","updatedAt":"2026-10-09T16:10:57.381Z"},{"id":"v_d09b46b7","type":"vote","entryId":"2a69b223","votedBelt":"Orange","comment":"Same one Rein picked. Very straightforward. Open keyway - Greenish","userId":"NdkmYGydSHfPTcj5xuqjwSyJJI42","displayName":"Greenish","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.381Z","updatedAt":"2026-10-09T16:11:57.381Z"},{"id":"v_e4c276d1","type":"vote","entryId":"2a69b223","votedBelt":"Green","comment":"green fits good.\\n6 pins, good tolerances, \\nThe T-pins can create a really nasty back and forth situation and need some good feeling between set and partially set pins.\\n\\nThe interactive element is set too easily and will not hinder any picking attempts in my oppinion.\\nThe Keyway is wide open which makes it easier.\\n- LockFumbler","userId":"gWoqbd0FOsglFD5boH96NAtJ7DE3","displayName":"LockFumbler","source":"Classification Sheet","createdAt":"2026-10-09T16:12:57.381Z","updatedAt":"2026-10-09T16:12:57.381Z"},{"id":"v_707fd72a","type":"vote","entryId":"08c823ed","votedBelt":"Black 1","comment":"LockChuck 8 Levers all with anti pick notches. Has to be picked twice to fully open. Different bitting on second pick. ","userId":"BuX3JAgrlzUW6Vz0L4W3YZK9iNw1","displayName":"LockChuck ","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.381Z","updatedAt":"2026-10-09T16:10:57.381Z"},{"id":"v_152d2583","type":"vote","entryId":"08c823ed","votedBelt":"Black 1","comment":"Borrowed LockChuck's 429. Needed fair amount of tension and patience. False gate = reset. I had to make sure any mid-lift or higher was preset. Most difficult lever lock I've picked yet, so I don't have much to compare it to. In terms of effort, it's on the border of BB1 and BB2 for me.  — Marson\\nhttps://youtu.be/_C2VW2RxWU8","userId":"e2RNiz570rWqYYxDSDn6Y0uhgA43","displayName":"Marson","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.381Z","updatedAt":"2026-10-09T16:11:57.381Z"},{"id":"v_1c2470a7","type":"vote","entryId":"e35a3c91","votedBelt":"Yellow","comment":"8 pins.  I've picked several of these now and only had to touch half the pins at most for any of them.  Some just needed two pins set.  A little hard to rank since they seem to range from white to orange roughly.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.383Z","updatedAt":"2026-10-09T16:10:57.383Z"},{"id":"v_75605d1a","type":"vote","entryId":"e35a3c91","votedBelt":"Yellow","comment":"Mine only had 1 active pin.... All the other drivers were too big to fit in the core. Ive heard of others getting ones like this too. I only say yellow because you need a flag. Kinda... Very disappointing. \\n-BurnB1","userId":"ogrEbc6fjmVOKtvfZ7vENh6oX072","displayName":"Burnetb1","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.383Z","updatedAt":"2026-10-09T16:11:57.383Z"},{"id":"v_99e4e3dd","type":"vote","entryId":"e35a3c91","votedBelt":"Orange","comment":"I've picked 10 of these, pinning varies. Some had 6 active stacks, some had 5. Top row pins are passive. Some required lifting only 3 pins while others required lifting 4 or 5 and depending where you start in the lock, you might have to lift more or fewer pins. I think they're harder than yellow, probably orange, but a novice picker might pick in circles for a while. Pins are easy to overset, zero's feel like they bind the whole time. LockPickingFisherman","userId":"IzvfeUBxzWcd8VXKHq0T4MUhtQu1","displayName":"LockPickingFisherman","source":"Classification Sheet","createdAt":"2026-10-09T16:12:57.383Z","updatedAt":"2026-10-09T16:12:57.383Z"},{"id":"v_d40fa9a0","type":"vote","entryId":"e35a3c91","votedBelt":"White","comment":"Mine only has one active pin as well. I just tapped it and it opened. — Marson","userId":"e2RNiz570rWqYYxDSDn6Y0uhgA43","displayName":"Marson","source":"Classification Sheet","createdAt":"2026-10-09T16:13:57.383Z","updatedAt":"2026-10-09T16:13:57.383Z"},{"id":"v_7ce47636","type":"vote","entryId":"b1949215","votedBelt":"Black 3","comment":"tonysansan\\n\\nEven with ideal tools this is a tough pick. You have to hit the pins at an angle with a combination of pushing and rotating, which torques the core and requires delicate tension control to compensate. Unlike the door lock, you need a minimum of 6 rigid tools, and they all knock into each other and mess with the tension.","userId":"BJyWOIOsqmRDkgHZBqIEGbGnVSA3","displayName":"tonysansan","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.383Z","updatedAt":"2026-10-09T16:10:57.383Z"},{"id":"v_fe036fdf","type":"vote","entryId":"e35772c9","votedBelt":"Black 5","comment":"tonysansan\\n\\nWhile I suppose this is technically a disc detainer lock, it feels like picking a 3KS around a corner through the keyway of a chain key lock without any tension control (reverse sidebar). There is very little room to maneuver around discs and idler, and no room for error — easy to overset and have to start over.","userId":"BJyWOIOsqmRDkgHZBqIEGbGnVSA3","displayName":"tonysansan","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.383Z","updatedAt":"2026-10-09T16:10:57.383Z"},{"id":"v_0ae6c47d","type":"vote","entryId":"267e47c4","votedBelt":"Brown","comment":"effective anti-pick that you cant pick out of, strong springs. two06","userId":"ohnGCeCEgIOk9KzmxWcsWmGM0nM2","displayName":"7woz3ro51x","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.383Z","updatedAt":"2026-10-09T16:10:57.383Z"},{"id":"v_1265b380","type":"vote","entryId":"267e47c4","votedBelt":"Brown","comment":"Tricky anti pick features and strong springs. levers also act tapered so lot of tension needed -Greenish","userId":"NdkmYGydSHfPTcj5xuqjwSyJJI42","displayName":"Greenish","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.383Z","updatedAt":"2026-10-09T16:11:57.383Z"},{"id":"v_0a127528","type":"vote","entryId":"dbc6670b","votedBelt":"Black 1","comment":"Lock Noob\\nhttps://discord.com/channels/140129091796992000/349621948713795594/1108796783242518588","userId":"u_c940f29e","displayName":"Lock Noob","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.384Z","updatedAt":"2026-10-09T16:10:57.384Z"},{"id":"v_f4941544","type":"vote","entryId":"c1c7e9d2","votedBelt":"Black 2","comment":"False gates are nasty and it's hard to avoid them.  False set means reset as does tripping the detector obviously.  3 levers with ‘active’ false gates.  Compression helps but on this one, the 6th lever has to be lifted higher than the tensioner so then there is no more compressing the lever pack. \\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.384Z","updatedAt":"2026-10-09T16:10:57.384Z"},{"id":"v_0bc9bdd4","type":"vote","entryId":"c2c1f8e0","votedBelt":"Purple","comment":"Mugatu\\nPipe key, 6 levers with false gates, good tolerances. Has another anti pick feature where a plunger effectively pushes down on the lever pack.","userId":"u_f278d262","displayName":"Mugatu","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.384Z","updatedAt":"2026-10-09T16:10:57.384Z"},{"id":"v_1059ac26","type":"vote","entryId":"22d70f2e","votedBelt":"Blue","comment":"Only 5 pins but small, tight keyway and a good mix of serrated and spool pins. Crispix ","userId":"bSkotjOGENXHGd3rpo8G3TJeCk33","displayName":"Crispix","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.384Z","updatedAt":"2026-10-09T16:10:57.384Z"},{"id":"v_db729b68","type":"vote","entryId":"2ae59863","votedBelt":"Brown","comment":"Not a true clone.  16 pins.  Not Clavis tolerances but very similar feeling lock.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.385Z","updatedAt":"2026-10-09T16:10:57.385Z"},{"id":"v_ed7b2908","type":"vote","entryId":"2ae59863","votedBelt":"Brown","comment":"NiXXeD\\n","userId":"WMSvvuutyShfvBBYB3PmDe4fmeS2","displayName":"NiXXeD","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.385Z","updatedAt":"2026-10-09T16:11:57.385Z"},{"id":"v_51b0a86a","type":"vote","entryId":"2ae59863","votedBelt":"Brown","comment":"Close to Clavis quality. 16 pins, same lock as sidepicks.\\n-BurnB1","userId":"ogrEbc6fjmVOKtvfZ7vENh6oX072","displayName":"Burnetb1","source":"Classification Sheet","createdAt":"2026-10-09T16:12:57.385Z","updatedAt":"2026-10-09T16:12:57.385Z"},{"id":"v_b5a7b191","type":"vote","entryId":"4d738de3","votedBelt":"Green","comment":"Even though on their homepage stands it should contain mushrooms I can't feel anything besides crunchy standard drivers. paracentric keyway, therefore yellow I think. \\nMoki","userId":"u_c3c19741","displayName":"Moki","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.385Z","updatedAt":"2026-10-09T16:10:57.385Z"},{"id":"v_0bbff29c","type":"vote","entryId":"955dbd20","votedBelt":"Black 5","comment":"tonysansan\\n\\nSignificantly harder than interior. Blocker is unpredictable, locking some levers in place from the start, and causing trouble for other levers throughout picking. Requires precise tensioning, differentiating feedback from both blocker and gates, and working some levers in pairs. Solid BB5.","userId":"BJyWOIOsqmRDkgHZBqIEGbGnVSA3","displayName":"tonysansan","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.387Z","updatedAt":"2026-10-09T16:10:57.387Z"},{"id":"v_01ebf309","type":"vote","entryId":"89207b78","votedBelt":"Brown","comment":"82 Deadlock.  5 levers, false gates, strong springs.  \\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.387Z","updatedAt":"2026-10-09T16:10:57.387Z"},{"id":"v_30ce018d","type":"vote","entryId":"cd5acff8","votedBelt":"Orange","comment":"mgsecure\\n\\n6-pin dimple with two spools. Available at UHS hardware, one of the few dimple options in the US","userId":"GGplAdctTfVDLVvYsfIADJmfp8f2","displayName":"mgsecure","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.387Z","updatedAt":"2026-10-09T16:10:57.387Z"},{"id":"v_70c3c2cf","type":"vote","entryId":"93324d19","votedBelt":"Blue","comment":"Mugatu\\nAwkward to tension, tensioning after the first 1/4 core lockup becomes an issue. All standard pins, did not act taper.\\nI'd say blue for the initial picked open position but could well see it purple for a full 360 given the tensioning complication.","userId":"u_f278d262","displayName":"Mugatu","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.388Z","updatedAt":"2026-10-09T16:10:57.388Z"},{"id":"v_c925da39","type":"vote","entryId":"352d0624","votedBelt":"Purple","comment":"clef\\nmaybe easy purple but i think hard blue.\\npassives pins on top align at 180° and you need to pick them to finish rotation","userId":"tbaq0CWuDTXerA0eUi0kGASVb1Z2","displayName":"Clefmentine","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.388Z","updatedAt":"2026-10-09T16:10:57.388Z"},{"id":"v_2ce4f425","type":"vote","entryId":"352d0624","votedBelt":"Blue","comment":"Jim","userId":"UbhgAjZIuLauV1dw2G4QsocHIk83","displayName":"Georgia Jim","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.388Z","updatedAt":"2026-10-09T16:11:57.388Z"},{"id":"v_e0e3245d","type":"vote","entryId":"352d0624","votedBelt":"Purple","comment":"easy purple IMO, still harder than most blue dimple locks I've picked \\n-DQ","userId":"qXhqtUdEVFfrajxqblKl8bqQqXM2","displayName":"DQ","source":"Classification Sheet","createdAt":"2026-10-09T16:12:57.388Z","updatedAt":"2026-10-09T16:12:57.388Z"},{"id":"v_06d41d68","type":"vote","entryId":"352d0624","votedBelt":"Purple","comment":"Really fun pick. The 360 really adds a good challenge. Mine has what appears to be barbell like pins and the ends are tiny spools. Purple sounds good. I wouldn't recommend this to someone looking for a blue lock. \\n-Nightmare","userId":"kBjhBaserkb0dTYBtgzNcLddnyy1","displayName":"Nightmare","source":"Classification Sheet","createdAt":"2026-10-09T16:13:57.388Z","updatedAt":"2026-10-09T16:13:57.388Z"},{"id":"v_3139648e","type":"vote","entryId":"81c91d86","votedBelt":"Green","comment":"Reinder's lock. Pretty straightforward, post makes tensioning awkward - Greenis","userId":"f2yySWbxUBXF8k3HgorYhrm76gx2","displayName":"Reinder","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.389Z","updatedAt":"2026-10-09T16:10:57.389Z"},{"id":"v_2fd77ac2","type":"vote","entryId":"476995cc","votedBelt":"Brown","comment":"6 levers.  I didn't gut but I didn't feel any false gates.  Pretty tricky lock for no false gates.  Very tapered and lever bind very hard.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.389Z","updatedAt":"2026-10-09T16:10:57.389Z"},{"id":"v_a1bb8b77","type":"vote","entryId":"97e1ae9f","votedBelt":"Black 1","comment":"CK (with standard drivers)","userId":"u_a970b935","displayName":"CK","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.389Z","updatedAt":"2026-10-09T16:10:57.389Z"},{"id":"v_b52307fe","type":"vote","entryId":"ca9828d7","votedBelt":"Brown","comment":"Jim\\nSlightly harder than TK5 with smooth fingers. Smooth sidebar with chamfering on the edges makes rotating serrated finger pins easier than even a smooth sidebar with 90° angles. Nowhere near black, and probably brown as both regular and 29sl primus are harder. ","userId":"UbhgAjZIuLauV1dw2G4QsocHIk83","displayName":"Georgia Jim","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.389Z","updatedAt":"2026-10-09T16:10:57.389Z"},{"id":"v_29de4508","type":"vote","entryId":"ca9828d7","votedBelt":"Red","comment":"yabende\\nMore difficult than TK5 and easier than SK6 Sperwelle Extra Code. In my opinion, red is fair","userId":"Gg9KxwHOwBf03QAIdOgZbfW3hRo1","displayName":"yabende","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.389Z","updatedAt":"2026-10-09T16:11:57.389Z"},{"id":"v_94d99024","type":"vote","entryId":"ca9828d7","votedBelt":"Brown","comment":"easier than the tk5 with serrated fingerpins, felt about as hard as the smooth ones and the extra pin did not do anything for the tops\\n-Alpama","userId":"FGhShmNkxTXC9vwmZwWylOvU8K72","displayName":"Alpama","source":"Classification Sheet","createdAt":"2026-10-09T16:12:57.389Z","updatedAt":"2026-10-09T16:12:57.389Z"},{"id":"v_07906ece","type":"vote","entryId":"ca9828d7","votedBelt":"Red","comment":"Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T16:13:57.389Z","updatedAt":"2026-10-09T16:13:57.389Z"},{"id":"v_4cf31d5f","type":"vote","entryId":"8d4632d9","votedBelt":"Blue","comment":"peace: similar to tubar, a little harder than fontaine except you don't need to 360°. Don't need special tensioner but it can obstruct a bit","userId":"mZyfQIARjCP1uJJJc7ioMAALV9v2","displayName":"PeaceWeapon","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.389Z","updatedAt":"2026-10-09T16:10:57.389Z"},{"id":"v_9f817cb0","type":"vote","entryId":"8d4632d9","votedBelt":"Purple","comment":"sameline with tubar because its a tubar\\n\\n-rein ","userId":"f2yySWbxUBXF8k3HgorYhrm76gx2","displayName":"Reinder","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.389Z","updatedAt":"2026-10-09T16:11:57.389Z"},{"id":"v_ff7b7014","type":"vote","entryId":"a7d98df3","votedBelt":"Red","comment":"I have a 15 pin variant and this thing is brutal, conservative red till other examples pop up. this is harder than most 20s I've picked.\\n-GravityKarma\\n ","userId":"8PKfUHTiafgObsQQr162dQRlBCo1","displayName":"GravityKarma","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.390Z","updatedAt":"2026-10-09T16:10:57.390Z"},{"id":"v_17a88283","type":"vote","entryId":"f97ad477","votedBelt":"Purple","comment":"12 pins in the lock I picked. Felt slightly tapered as little taps would give some core movement. Had to pick CW because cam. \\n\\n-Nightmare","userId":"kBjhBaserkb0dTYBtgzNcLddnyy1","displayName":"Nightmare","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.390Z","updatedAt":"2026-10-09T16:10:57.390Z"},{"id":"v_1bed245f","type":"vote","entryId":"fe9889e2","votedBelt":"Red","comment":"yabende\\n14 pins. Poor feedback and some weird pins - the keypin has a dimple in the base and the driver pin is convex, like a half sphere - quite problematic positioning with disturbed feedback","userId":"Gg9KxwHOwBf03QAIdOgZbfW3hRo1","displayName":"yabende","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.390Z","updatedAt":"2026-10-09T16:10:57.390Z"},{"id":"v_495d243a","type":"vote","entryId":"fe9889e2","votedBelt":"Red","userId":"u_490173df","displayName":"Unknown","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.390Z","updatedAt":"2026-10-09T16:11:57.390Z"},{"id":"v_69719b9b","type":"vote","entryId":"991c6c07","votedBelt":"Purple","comment":"A bit harder then 29a/b. Not by a lot IMHO -Retep","userId":"u_7e351cf1","displayName":"Retep","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.391Z","updatedAt":"2026-10-09T16:10:57.391Z"},{"id":"v_75695a5b","type":"vote","entryId":"c65959a3","votedBelt":"Purple","comment":"Primary feedback is audio.  Bit of trial and error figuring out true and false gates but gets a little easier as you get more wheels in true gates.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.391Z","updatedAt":"2026-10-09T16:10:57.391Z"},{"id":"v_202a1e6e","type":"vote","entryId":"64662298","votedBelt":"Green","comment":"clef\\nno anti pick just 7 pins\\nall side pins do not have to be touched for picking.\\nusually mastered","userId":"tbaq0CWuDTXerA0eUi0kGASVb1Z2","displayName":"Clefmentine","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.391Z","updatedAt":"2026-10-09T16:10:57.391Z"},{"id":"v_5f625e82","type":"vote","entryId":"64662298","votedBelt":"Green","userId":"u_b73b3624","displayName":"Unknown","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.391Z","updatedAt":"2026-10-09T16:11:57.391Z"},{"id":"v_4cc1721e","type":"vote","entryId":"8e11009a","votedBelt":"Blue","comment":"clef\\n5 pin dimple lock 2 barrels and 3 spools.\\nthe picking is not hard you just need to be carefull to not set the alarm.\\nalarm is trigered by vibration on pushing the pin inside the cam","userId":"tbaq0CWuDTXerA0eUi0kGASVb1Z2","displayName":"Clefmentine","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.392Z","updatedAt":"2026-10-09T16:10:57.392Z"},{"id":"v_8166c313","type":"vote","entryId":"1dd55e66","votedBelt":"Brown","comment":"Interesting lock. 7 security drivers and also security keypins which are all tapered a bit + additional 4 slider wafer combined with 6 sidebar pins whereas 5 of them interact each with the slider wafer in overlapping type. \\nI found the feedback of the mainpins far away from easy to tell the state and also the slider wafers are kinda interesting if picked one by one.\\nA lot of ping pong like with tapers because of the interaction of the slider wafers and the sidebar pins. \\nYeah I had to invent new words for that 😅 I think with my pinning it can’t be on the same level as milenco magnum and all those other locks on purple. So I judge it to be brown belt. There is a flaw about depending on the slider wafers bitting to full lift all might work to open the lock after picking the main pins. \\n\\nSee video for better understanding. \\n\\nhttps://youtu.be/2licUMd_zb0?si=MnShQN_Vu1hRrsON\\n\\nThanks,  ~ Dig 09.12.2025","userId":"U3wCYsdGwYS8ujsO2K78iD68FMC3","displayName":"Dig","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.392Z","updatedAt":"2026-10-09T16:10:57.392Z"},{"id":"v_ea7c7df0","type":"vote","entryId":"45bb95df","votedBelt":"Red","comment":"Same as the base codkey locksys 15 pinner but one of the chambers is replaced with steel pin that's sprug outwards of the core. The warding makes it very difficult to position the magnet on the right spot and for me it didn't work to put it at the end when everything else was picked. Defiently harder than the base codkey wich is rated brown so I'll give this one red, not sure if it deserves bb1 \\n-DQ ","userId":"qXhqtUdEVFfrajxqblKl8bqQqXM2","displayName":"DQ","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.393Z","updatedAt":"2026-10-09T16:10:57.393Z"},{"id":"v_733d1bf5","type":"vote","entryId":"45bb95df","votedBelt":"Red","comment":"Red IMO\\nyabende","userId":"Gg9KxwHOwBf03QAIdOgZbfW3hRo1","displayName":"yabende","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.393Z","updatedAt":"2026-10-09T16:11:57.393Z"},{"id":"v_890b5729","type":"vote","entryId":"45bb95df","votedBelt":"Brown","comment":"the magnetic element is negligible imo, get a magnet in there and pick like normal \\n\\n-rein","userId":"f2yySWbxUBXF8k3HgorYhrm76gx2","displayName":"Reinder","source":"Classification Sheet","createdAt":"2026-10-09T16:12:57.393Z","updatedAt":"2026-10-09T16:12:57.393Z"},{"id":"v_b241e72f","type":"vote","entryId":"f74e0e97","votedBelt":"Brown","comment":"comes pinned with standards but picked to both shears along with the sliders it's not the easiest.\\n(note, i picked it with m2 pins)\\n-rein","userId":"f2yySWbxUBXF8k3HgorYhrm76gx2","displayName":"Reinder","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.394Z","updatedAt":"2026-10-09T16:10:57.394Z"},{"id":"v_49cd7074","type":"vote","entryId":"f74e0e97","votedBelt":"Brown","userId":"u_5dc3fe1b","displayName":"Unknown","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.394Z","updatedAt":"2026-10-09T16:11:57.394Z"},{"id":"v_86ace9e3","type":"vote","entryId":"a6f31065","votedBelt":"Orange","comment":"Peace: 6 pins, spools, good orange pick","userId":"mZyfQIARjCP1uJJJc7ioMAALV9v2","displayName":"PeaceWeapon","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.394Z","updatedAt":"2026-10-09T16:10:57.394Z"},{"id":"v_86a6beca","type":"vote","entryId":"a6f31065","votedBelt":"Orange","comment":"LockPickingFisherman\\nEssentially the same as Master 1145, in a different body. 5 spools,  serrated in chamber 1. Same fairly open keyway. 1145 and 2950EURD could be samelined imo. Both are fun, good intro's to dimples.","userId":"IzvfeUBxzWcd8VXKHq0T4MUhtQu1","displayName":"LockPickingFisherman","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.394Z","updatedAt":"2026-10-09T16:11:57.394Z"},{"id":"v_bf36e27e","type":"vote","entryId":"ad46dc5a","votedBelt":"Brown","comment":"Skwiggledork https://discord.com/channels/140129091796992000/349621948713795594/1242980065067925574","userId":"zDpOLv3IAPSdIwPpSPGf8cKQumx2","displayName":"Skwiggs","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.395Z","updatedAt":"2026-10-09T16:10:57.395Z"},{"id":"v_235bccbf","type":"vote","entryId":"ad46dc5a","votedBelt":"Red","comment":"Onlypins,\\n\\nI feel like the tolerances and the security features of the 5/3 is still just as tough as the 6/4. ","userId":"pa0Fe38BgdV9fcL5PPNToNd7NVU2","displayName":"OnlyPins","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.395Z","updatedAt":"2026-10-09T16:11:57.395Z"},{"id":"v_5dd3c071","type":"vote","entryId":"ad46dc5a","votedBelt":"Brown","comment":"all the ones I've seen are milled for 6/4 so shouldn't be red. especially the open side milling with all the min lifts\\nmasterlocksux","userId":"Kvf5QQTos8OCbgr8AkULzkWjVqr1","displayName":"MasterLockSux","source":"Classification Sheet","createdAt":"2026-10-09T16:12:57.395Z","updatedAt":"2026-10-09T16:12:57.395Z"},{"id":"v_1a1c696b","type":"vote","entryId":"e6872b30","votedBelt":"Orange","comment":"Lock Noob","userId":"u_c940f29e","displayName":"Lock Noob","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.396Z","updatedAt":"2026-10-09T16:10:57.396Z"},{"id":"v_4171e57f","type":"vote","entryId":"fb472463","votedBelt":"Green","comment":"NiXXeD\\nThis one had a favorable bitting. Pretty bad keyway could make any low/highs much more challenging than this, and I could easily see this being blue.","userId":"WMSvvuutyShfvBBYB3PmDe4fmeS2","displayName":"NiXXeD","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.396Z","updatedAt":"2026-10-09T16:10:57.396Z"},{"id":"v_76275cbb","type":"vote","entryId":"fb472463","votedBelt":"Blue","comment":"Nasty keyway for max lifts especially behind low lifts.  Put up more of a fight than I expected.  Thin lipped drivers were effective and gave some ping pong.\\n-Sidepicks ","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.396Z","updatedAt":"2026-10-09T16:11:57.396Z"},{"id":"v_7d75fa39","type":"vote","entryId":"4150776b","votedBelt":"Black 1","userId":"u_3c15bdf5","displayName":"Unknown","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.396Z","updatedAt":"2026-10-09T16:10:57.396Z"},{"id":"v_c9d8e124","type":"vote","entryId":"4150776b","votedBelt":"Black 1","comment":"the 6 rows make pretty cramped and annoying to navigate. it's easy to overset low rows while going for the middle ones. and as usual excellent tolerances.\\n-rein","userId":"f2yySWbxUBXF8k3HgorYhrm76gx2","displayName":"Reinder","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.396Z","updatedAt":"2026-10-09T16:11:57.396Z"},{"id":"v_a833cd3e","type":"vote","entryId":"ea4834c8","votedBelt":"Red","comment":"Red Wanderer - 14 pin 3 row dimple, lots of spool pins and some overset traps on the sides. Plug is lightly milled. Offset warding is kind of a pain. Seems fair to rank it in line with low pin count v18s, it's basically a clone although the plug isn't drilled for more pins than I had in mine.\\n\\nhttps://youtu.be/f2CQQd7Ch9Q","userId":"XoUDXU5McjTuVnPA1xfmzytcKuy2","displayName":"Red Wanderer","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.398Z","updatedAt":"2026-10-09T16:10:57.398Z"},{"id":"v_99099f5c","type":"vote","entryId":"ea4834c8","votedBelt":"Red","comment":"Feels and looks very similar to the Showa NX, even has basically the same warding.  Loaner from Red but different lock than the one he ranked.  This one had 13 pin stacks, 1 dummy stack, and 1 centering bearing stack.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.398Z","updatedAt":"2026-10-09T16:11:57.398Z"},{"id":"v_c9e360f6","type":"vote","entryId":"3bfcd36c","votedBelt":"Blue","userId":"u_8dfd2b20","displayName":"Unknown","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.398Z","updatedAt":"2026-10-09T16:10:57.398Z"},{"id":"v_e29f552c","type":"vote","entryId":"3bfcd36c","votedBelt":"Blue","comment":"Lots of pins, but they all felt standard and some set just by scrubbing. \\n\\n-Nightmare\\n","userId":"kBjhBaserkb0dTYBtgzNcLddnyy1","displayName":"Nightmare","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.398Z","updatedAt":"2026-10-09T16:11:57.398Z"},{"id":"v_72814024","type":"vote","entryId":"3bfcd36c","votedBelt":"Blue","comment":"12 standard pins 3 rows. feels low to middle blue \\nBrianBreaksShit ","userId":"tUMX51TojfWcZxzqpiPYKTnOnQg1","displayName":"BrianBreaksShit ","source":"Classification Sheet","createdAt":"2026-10-09T16:12:57.398Z","updatedAt":"2026-10-09T16:12:57.398Z"},{"id":"v_9129c7e5","type":"vote","entryId":"3bfcd36c","votedBelt":"Blue","comment":"Blue feels pretty fair.  12 pins that all feel standard and set mostly with a light scrub. \\nKlettus","userId":"nOCg2aCpEgOI5lJOxwyScW9kXFX2","displayName":"Klettus","source":"Classification Sheet","createdAt":"2026-10-09T16:13:57.398Z","updatedAt":"2026-10-09T16:13:57.398Z"},{"id":"v_62d8dd96","type":"vote","entryId":"c6cd3574","votedBelt":"Red","comment":"Weird and confusing.  6 Pins?/sliders? (3 on each side) that need lifted and rotated.  Very subtle feedback, almost nonexistent.  Everything is springy even when it's binding.  Even when it's picked and core is rotated all the pins are so springy that it needs a key retention mechanism (dimple in key and ball bearing in the core).  Key would be removable with core turned otherwise.  Would also agree with BB1.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.398Z","updatedAt":"2026-10-09T16:10:57.398Z"},{"id":"v_549ab150","type":"vote","entryId":"2ac99741","votedBelt":"Blue","comment":"clef\\neasy to tension\\na bit tapered, difficulty come from the fact than during the picking the internal rotate to a point where you can not reach the pins without super fin tools and move arround","userId":"tbaq0CWuDTXerA0eUi0kGASVb1Z2","displayName":"Clefmentine","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.399Z","updatedAt":"2026-10-09T16:10:57.399Z"},{"id":"v_6830645b","type":"vote","entryId":"2ac99741","votedBelt":"Blue","comment":"Peace: easy enough to pick the first few ones once you make a simple tensioner that works. but last few picks are way behind the fixed face plate, not easy to reach for.","userId":"mZyfQIARjCP1uJJJc7ioMAALV9v2","displayName":"PeaceWeapon","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.399Z","updatedAt":"2026-10-09T16:11:57.399Z"},{"id":"v_21e1abee","type":"vote","entryId":"3ca24202","votedBelt":"Purple","comment":"Craig: this felt purple to me. Some pins have to be mapped out because they bind no matter what, due to the second shearline, but the rest are easy. Could be a lot of variation with these.","userId":"u_9a4c8f0f","displayName":"Craig","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.399Z","updatedAt":"2026-10-09T16:10:57.399Z"},{"id":"v_ad6ef3c1","type":"vote","entryId":"3ca24202","votedBelt":"Purple","comment":"clef\\nsame as pollux 5 but most of them are mastered so two sheer lines can be really tricky if the lock is dusty","userId":"tbaq0CWuDTXerA0eUi0kGASVb1Z2","displayName":"Clefmentine","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.399Z","updatedAt":"2026-10-09T16:11:57.399Z"},{"id":"v_d98c105a","type":"vote","entryId":"3ca24202","votedBelt":"Purple","comment":"felt purple, keyway is easily open and the feedback is generally ok except for one or two pin that are mushy. not too hard but the mushy pins can really gunk up your feeling until you almost stumble into the open\\n-Alpama","userId":"FGhShmNkxTXC9vwmZwWylOvU8K72","displayName":"Alpama","source":"Classification Sheet","createdAt":"2026-10-09T16:12:57.399Z","updatedAt":"2026-10-09T16:12:57.399Z"},{"id":"v_f4775168","type":"vote","entryId":"f5086cb9","votedBelt":"Purple","comment":"Like Pollux 7 but with master ring. Pretty straightforward. Tap tap tap. Gutting is tricky. - Greenish","userId":"NdkmYGydSHfPTcj5xuqjwSyJJI42","displayName":"Greenish","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.400Z","updatedAt":"2026-10-09T16:10:57.400Z"},{"id":"v_6263636d","type":"vote","entryId":"f5086cb9","votedBelt":"Purple","comment":"clef\\n","userId":"tbaq0CWuDTXerA0eUi0kGASVb1Z2","displayName":"Clefmentine","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.400Z","updatedAt":"2026-10-09T16:11:57.400Z"},{"id":"v_e0aec4a9","type":"vote","entryId":"f5086cb9","votedBelt":"Brown","comment":"Tapers tapers tapers. Mastering makes the gutting a bit tricky.\\n-baikunz","userId":"YYh4QtNUrba1xOqNm9z2GqG7ssO2","displayName":"baikunz","source":"Classification Sheet","createdAt":"2026-10-09T16:12:57.400Z","updatedAt":"2026-10-09T16:12:57.400Z"},{"id":"v_28f57018","type":"vote","entryId":"f5086cb9","votedBelt":"Brown","comment":"Picks the same as the Pollux 7, pretty much, maybe a bit more tapered action in this. Not much different\\n-Zehkar","userId":"1SqcRKce18boUZBtOHWSenGAI202","displayName":"Zehkar","source":"Classification Sheet","createdAt":"2026-10-09T16:13:57.400Z","updatedAt":"2026-10-09T16:13:57.400Z"},{"id":"v_da9cc07e","type":"vote","entryId":"f5086cb9","votedBelt":"Brown","comment":"Mine was a bit harder than my Pollux 7.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T16:14:57.400Z","updatedAt":"2026-10-09T16:14:57.400Z"},{"id":"v_4ff9647c","type":"vote","entryId":"9637ddde","votedBelt":"Brown","comment":"This is a complex dimple lock with effective sliders. Could be red, could be brown. I've only seen 1 -\\n GravityKarma\\n","userId":"8PKfUHTiafgObsQQr162dQRlBCo1","displayName":"GravityKarma","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.400Z","updatedAt":"2026-10-09T16:10:57.400Z"},{"id":"v_9de7661e","type":"vote","entryId":"aaca6c85","votedBelt":"Blue","comment":"Could be samelined with MTL/Kenaurd.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.400Z","updatedAt":"2026-10-09T16:10:57.400Z"},{"id":"v_3ec19c67","type":"vote","entryId":"aaca6c85","votedBelt":"Blue","comment":"NiXXeD\\nFelt like Kenaurd. Chase the binder.","userId":"WMSvvuutyShfvBBYB3PmDe4fmeS2","displayName":"NiXXeD","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.400Z","updatedAt":"2026-10-09T16:11:57.400Z"},{"id":"v_88b6fa2b","type":"vote","entryId":"aaca6c85","votedBelt":"Blue","comment":"Same lock as sidepicks. Feels worse than MTL to me.\\n-BurnB1","userId":"ogrEbc6fjmVOKtvfZ7vENh6oX072","displayName":"Burnetb1","source":"Classification Sheet","createdAt":"2026-10-09T16:12:57.400Z","updatedAt":"2026-10-09T16:12:57.400Z"},{"id":"v_83bfa155","type":"vote","entryId":"6cb514ea","votedBelt":"Blue","comment":"Jim\\nLower tolerance MTL Interactive clone.  Mix of standard and spools (3 spool, 2 standard) blue at 5 pins, green at 4 pins. ","userId":"UbhgAjZIuLauV1dw2G4QsocHIk83","displayName":"Georgia Jim","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.401Z","updatedAt":"2026-10-09T16:10:57.401Z"},{"id":"v_8542d7a1","type":"vote","entryId":"6cb514ea","votedBelt":"Purple","comment":"mgsecure. poor tolerances, might rank blue but we have the \\"Any MTL Interactive Clone\\" entry at Purple. Pics at https://lpubelts.com/#/locks?search=ri-&tab=search&id=6cb514ea&name=RiKey_High_Security_MTL_clone\\n","userId":"GGplAdctTfVDLVvYsfIADJmfp8f2","displayName":"mgsecure","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.401Z","updatedAt":"2026-10-09T16:11:57.401Z"},{"id":"v_c08c850a","type":"vote","entryId":"6cb514ea","votedBelt":"Green","comment":" Agree with J.im. 4 pin should be Green. I'd hate to have more splits on these PIPs, but manufacturing quality does vary. -VectorPotential\\n","userId":"6dSEXTn8flPPg4EV5IlSQWGVT983","displayName":"VectorPotential","source":"Classification Sheet","createdAt":"2026-10-09T16:12:57.401Z","updatedAt":"2026-10-09T16:12:57.401Z"},{"id":"v_f410a356","type":"vote","entryId":"6cb514ea","votedBelt":"Blue","comment":"Spy-c, I agree with J.im and Vector 4 pin green/5 pin blue it sits somewhere between Kenuard and Deguard in my head","userId":"VBmk1eBTsyeE3MqvDJMRrWoM3mt1","displayName":"Spyc","source":"Classification Sheet","createdAt":"2026-10-09T16:13:57.401Z","updatedAt":"2026-10-09T16:13:57.401Z"},{"id":"v_dec56f17","type":"vote","entryId":"6cb514ea","votedBelt":"Blue","comment":"I dont even know why we have \\"Any HQ Interactive Clone\\" if we're going to rank each one. Imo remove that entry and RiKey 4pin at Green and RiKey 5 pin at Blue.\\n\\nI don't think it deserves Purple like MTL because at least my examples are quite loose and unlike MTL it requires some very sloppy picking to drop any set spools.\\n~Bugasu","userId":"qtp7IM8d9sawUEAKsM0vwMITexR2","displayName":"Bugasu","source":"Classification Sheet","createdAt":"2026-10-09T16:14:57.401Z","updatedAt":"2026-10-09T16:14:57.401Z"},{"id":"v_4a208570","type":"vote","entryId":"6cb514ea","votedBelt":"Blue","userId":"u_131ffcd3","displayName":"Unknown","source":"Classification Sheet","createdAt":"2026-10-09T16:15:57.401Z","updatedAt":"2026-10-09T16:15:57.401Z"},{"id":"v_e3736161","type":"vote","entryId":"d87bb501","votedBelt":"Yellow","comment":"5 pin all standards but is one of the trickier 5 pin standard locks I've picked.  Easy to overset.  I would agree with orange as well.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.401Z","updatedAt":"2026-10-09T16:10:57.401Z"},{"id":"v_250c265a","type":"vote","entryId":"d87bb501","votedBelt":"Orange","comment":"Spy-c, some higher lifts in mine that made me wish I had one at orange to teach me about warding as a ledge and bok inserts for height","userId":"VBmk1eBTsyeE3MqvDJMRrWoM3mt1","displayName":"Spyc","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.401Z","updatedAt":"2026-10-09T16:11:57.401Z"},{"id":"v_1e07c26b","type":"vote","entryId":"9b528165","votedBelt":"Purple","comment":"purple/brown, it's like a smaller 32a and has only 6 disks\\n\\n-rein","userId":"f2yySWbxUBXF8k3HgorYhrm76gx2","displayName":"Reinder","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.401Z","updatedAt":"2026-10-09T16:10:57.401Z"},{"id":"v_d6ceeedd","type":"vote","entryId":"5646568c","votedBelt":"Black 5","comment":"tonysansan\\n\\nThere are deep false gates everywhere. Requires delicate motions to determine disc state and to advance step by step without oversetting. Easy to touch a disc and knock it out of position. One error and the picking attempt is over.","userId":"BJyWOIOsqmRDkgHZBqIEGbGnVSA3","displayName":"tonysansan","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.401Z","updatedAt":"2026-10-09T16:10:57.401Z"},{"id":"v_f05a7ccb","type":"vote","entryId":"d78c58be","votedBelt":"Purple","comment":"I picked it both w/ 2-in-1 and w/ wire. Tapered & false gates. Needs gobs of tension. Already has an unranked entry w/ photos.\\n-Marson","userId":"e2RNiz570rWqYYxDSDn6Y0uhgA43","displayName":"Marson","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.402Z","updatedAt":"2026-10-09T16:10:57.402Z"},{"id":"v_85f86b34","type":"vote","entryId":"d78c58be","votedBelt":"Purple","comment":"Agree with M.arson. Effective false gates, needed to pre-lift some levers. Lots of tension. Picked with wire - Greenish","userId":"NdkmYGydSHfPTcj5xuqjwSyJJI42","displayName":"Greenish","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.402Z","updatedAt":"2026-10-09T16:11:57.402Z"},{"id":"v_a30e5acb","type":"vote","entryId":"e713e7e6","votedBelt":"Green","comment":"Peace: pretty fun. Challenging enough","userId":"mZyfQIARjCP1uJJJc7ioMAALV9v2","displayName":"PeaceWeapon","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.402Z","updatedAt":"2026-10-09T16:10:57.402Z"},{"id":"v_7f2f3510","type":"vote","entryId":"e713e7e6","votedBelt":"Blue","comment":"Yagias:\\nGood fun and much trickier than say an ACE II, Requires custom tensioning tool.","userId":"u_89015b15","displayName":"Yagias","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.402Z","updatedAt":"2026-10-09T16:11:57.402Z"},{"id":"v_635cb663","type":"vote","entryId":"e713e7e6","votedBelt":"Blue","comment":"spring from the lock make it hard to tension and after it's 5 tappered pins it goes pok pok pok and open\\nclef","userId":"tbaq0CWuDTXerA0eUi0kGASVb1Z2","displayName":"Clefmentine","source":"Classification Sheet","createdAt":"2026-10-09T16:12:57.402Z","updatedAt":"2026-10-09T16:12:57.402Z"},{"id":"v_f3bc332f","type":"vote","entryId":"8a7eee5c","votedBelt":"Red","comment":"I believe it's around red belt level- the levers are very close together a d it's easy to slip off or move 2 levers instead of one, also requires floatpicking - my video here: https://youtu.be/KzGpTGLaY6Y?si=RE_e1Jgaa80xcegf\\n-DQ","userId":"qXhqtUdEVFfrajxqblKl8bqQqXM2","displayName":"DQ","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.403Z","updatedAt":"2026-10-09T16:10:57.403Z"},{"id":"v_b268b34d","type":"vote","entryId":"a72739bc","votedBelt":"Black 2","comment":"This lock is a struggle. Very easy to unset pins, requires all custom non-magnetic tooling, the very limited space is a challenge of its own, and some of the chambers have a kind of reverse T effect that drops you into a nasty \\"false set\\".\\n- DND","userId":"XKPQaAR525XV2JsqGn12eEKwxD62","displayName":"DoNotDuplicate","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.403Z","updatedAt":"2026-10-09T16:10:57.403Z"},{"id":"v_6a97c1f5","type":"vote","entryId":"55d4676c","votedBelt":"Blue","comment":"8 pins with 3 sprung sliders.  Very similar to Yale 2000 plus, DAF Kilit, and Mottura Viper.  I don't know if the 2 less pins and one less slider is enough for a belt drop but it could be.  All these locks are fairly similar and fairly easy but very fun.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.404Z","updatedAt":"2026-10-09T16:10:57.404Z"},{"id":"v_315e6117","type":"vote","entryId":"55d4676c","votedBelt":"Purple","comment":"NiXXeD\\nNot quite easy enough for blue imo. Felt really similar to the Yale like this.","userId":"WMSvvuutyShfvBBYB3PmDe4fmeS2","displayName":"NiXXeD","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.404Z","updatedAt":"2026-10-09T16:11:57.404Z"},{"id":"v_10ae9615","type":"vote","entryId":"55d4676c","votedBelt":"Purple","comment":"Same lock as Side.picks\\n-BurnB1","userId":"ogrEbc6fjmVOKtvfZ7vENh6oX072","displayName":"Burnetb1","source":"Classification Sheet","createdAt":"2026-10-09T16:12:57.404Z","updatedAt":"2026-10-09T16:12:57.404Z"},{"id":"v_38d41720","type":"vote","entryId":"55d4676c","votedBelt":"Purple","comment":"Red Wanderer - Same lock as Nix.xed. Definitely in the high blue - purple range. Sliders didn't feel consequential, but the high lift pins are rough and the spools tend to drop things.","userId":"XoUDXU5McjTuVnPA1xfmzytcKuy2","displayName":"Red Wanderer","source":"Classification Sheet","createdAt":"2026-10-09T16:13:57.404Z","updatedAt":"2026-10-09T16:13:57.404Z"},{"id":"v_e5a75908","type":"vote","entryId":"6c395573","votedBelt":"Black 2","comment":"Appears to be a near exact reproduction of the Segal Pickproof.  5 pins with different diameter key pins, spooled gin drivers that get stuck in the floating slotted sleeve if not set to the proper height.  If core is turned before all spooled gins are above the sleeve it basically forces a reset.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.404Z","updatedAt":"2026-10-09T16:10:57.404Z"},{"id":"v_695f1078","type":"vote","entryId":"6c395573","votedBelt":"Black 2","comment":"tonysansan\\n\\nSleeve makes main pins much harder than those of 6k with gins, though there is one fewer pin and no sidebar.","userId":"BJyWOIOsqmRDkgHZBqIEGbGnVSA3","displayName":"tonysansan","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.404Z","updatedAt":"2026-10-09T16:11:57.404Z"},{"id":"v_a37873b2","type":"vote","entryId":"452aaa17","votedBelt":"Orange","comment":"Mugatu\\n3 levers on each side of pipe pin, one sheet of metal warding seperating levers 1 from 2&3. Levers interact directly with the shackle.","userId":"u_f278d262","displayName":"Mugatu","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.404Z","updatedAt":"2026-10-09T16:10:57.404Z"},{"id":"v_5173dee5","type":"vote","entryId":"97baf67b","votedBelt":"White","comment":"\\nPanda-Frog","userId":"u_93bfb607","displayName":"Panda Frog","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.405Z","updatedAt":"2026-10-09T16:10:57.405Z"},{"id":"v_2bec5ccb","type":"vote","entryId":"0d0bf1a5","votedBelt":"White","comment":"\\nPanda-Frog","userId":"u_93bfb607","displayName":"Panda Frog","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.405Z","updatedAt":"2026-10-09T16:10:57.405Z"},{"id":"v_86480a84","type":"vote","entryId":"29d423c8","votedBelt":"Yellow","comment":"Panda-Frog","userId":"u_93bfb607","displayName":"Panda Frog","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.405Z","updatedAt":"2026-10-09T16:10:57.405Z"},{"id":"v_d8c04890","type":"vote","entryId":"53365ed3","votedBelt":"Orange","comment":"Panda-Frog","userId":"u_93bfb607","displayName":"Panda Frog","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.405Z","updatedAt":"2026-10-09T16:10:57.405Z"},{"id":"v_5fb7aecb","type":"vote","entryId":"6d63be2d","votedBelt":"Yellow","comment":"Both the brass and stainless levers are more slippery than the forged steel ones in the 440, but I don't know if it bumps it up another rank. I'd be fine with either yellow or orange.\\n — Marson","userId":"e2RNiz570rWqYYxDSDn6Y0uhgA43","displayName":"Marson","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.405Z","updatedAt":"2026-10-09T16:10:57.405Z"},{"id":"v_bfad679b","type":"vote","entryId":"a77899fe","votedBelt":"Blue","comment":"Jim","userId":"UbhgAjZIuLauV1dw2G4QsocHIk83","displayName":"Georgia Jim","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.406Z","updatedAt":"2026-10-09T16:10:57.406Z"},{"id":"v_0a412018","type":"vote","entryId":"174e20c0","votedBelt":"Brown","comment":"Small with unusual feedback and navigation, but ok manipulation once understood.\\ncrispix ","userId":"bSkotjOGENXHGd3rpo8G3TJeCk33","displayName":"Crispix","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.406Z","updatedAt":"2026-10-09T16:10:57.406Z"},{"id":"v_ba572f7d","type":"vote","entryId":"9a99a0a7","votedBelt":"White","comment":"Old model but sometimes available secondhand. 4 standard pins, nothing fancy.\\nMoki","userId":"u_c3c19741","displayName":"Moki","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.407Z","updatedAt":"2026-10-09T16:10:57.407Z"},{"id":"v_f53d9c48","type":"vote","entryId":"9d35efa9","votedBelt":"Yellow","comment":"NiXXeD\\nVery simple pick, very interesting insides","userId":"WMSvvuutyShfvBBYB3PmDe4fmeS2","displayName":"NiXXeD","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.407Z","updatedAt":"2026-10-09T16:10:57.407Z"},{"id":"v_602a1962","type":"vote","entryId":"9d35efa9","votedBelt":"Yellow","comment":"Cool rekeying mechanism.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.407Z","updatedAt":"2026-10-09T16:11:57.407Z"},{"id":"v_5deb47c8","type":"vote","entryId":"288c8f6e","votedBelt":"Blue","comment":"DECODER: Not much difference to Winkhaus N-tra and other similar dimple locks","userId":"Mwbvdkq1QtWu2zLwEaj3imULSry1","displayName":"decoder","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.408Z","updatedAt":"2026-10-09T16:10:57.408Z"},{"id":"v_771a1cbc","type":"vote","entryId":"10679814","votedBelt":"Blue","comment":"DECODER: Only picked it once, don't have one for retrying. Seemed not so straightforward.","userId":"Mwbvdkq1QtWu2zLwEaj3imULSry1","displayName":"decoder","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.408Z","updatedAt":"2026-10-09T16:10:57.408Z"},{"id":"v_5ccdb00c","type":"vote","entryId":"10679814","votedBelt":"Blue","comment":"Need to 360\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T16:11:57.408Z","updatedAt":"2026-10-09T16:11:57.408Z"},{"id":"v_c8d6540f","type":"vote","entryId":"c4a2fbe5","votedBelt":"Blue","comment":"Could be green, no security pins, drivers and key pins are rounded where they meet at shear. Only rated blue because you need to search for the binder in the 3 rows. 17 pins in mine.\\n-Mugatu","userId":"u_f278d262","displayName":"Mugatu","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.409Z","updatedAt":"2026-10-09T16:10:57.409Z"},{"id":"v_d141eab8","type":"vote","entryId":"e16080de","votedBelt":"Blue","comment":"I picked one from Arti's group buy. \\n The keyway on the customer side is the only real challenge and the bitting of this particular lock with the max or near max lift on #6.  I don't know if all these have the same or similar keyway, but my rating is just based on the one I picked.  If not for the customer keyway and bitting I feel this would be green.\\n-Sidepicks","userId":"pzSak8xusHdeNlD0JmTru5kMrww2","displayName":"Sidepicks","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.409Z","updatedAt":"2026-10-09T16:10:57.409Z"},{"id":"v_54c6c079","type":"vote","entryId":"ad6b0d8f","votedBelt":"Yellow","comment":"LockPickingFisherman\\n5 stacks with brass standard drivers in an aluminum body. Muted feedback. It's a weird pick but also kinda fun. A little rougher than Master 141 but not much harder. Definitely not up to orange imho.","userId":"IzvfeUBxzWcd8VXKHq0T4MUhtQu1","displayName":"LockPickingFisherman","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.409Z","updatedAt":"2026-10-09T16:10:57.409Z"},{"id":"v_c5992052","type":"vote","entryId":"a7ffa199","votedBelt":"Green","comment":"6 standards, 2 spools with poor tolerances. Could feel shifts in the core setting standard pins. Keyway isn’t really restrictive, was able to use tall MP flags to set pins. ","userId":"u_77e04c0d","displayName":"Unknown","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.409Z","updatedAt":"2026-10-09T16:10:57.409Z"},{"id":"v_40180e85","type":"vote","entryId":"2b6dd267","votedBelt":"Blue","comment":"9 pin plus interactive rather than the stated 8, 2 spools, 1 torpedo keypin, can be a bit tricky if the spool is under a max lift pin, rows don't isolate so some jumping about including the interactive which binds either first clockwise our next to last counterclockwise on the lock I had, could be purple perhaps \\nLockpickingPaul","userId":"SyjMMYh9rYPI0lrxAWu5z5rrawx2","displayName":"Lock Picking Paul","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.409Z","updatedAt":"2026-10-09T16:10:57.409Z"},{"id":"v_8fec711a","type":"vote","entryId":"0757b1ed","votedBelt":"Green","comment":"Poor tolerances and rounded key pins and lack of security pins keep this at green with the other models imo.\\n\\nJim","userId":"UbhgAjZIuLauV1dw2G4QsocHIk83","displayName":"Georgia Jim","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.409Z","updatedAt":"2026-10-09T16:10:57.409Z"},{"id":"v_654c6ecf","type":"vote","entryId":"074db05e","votedBelt":"Green","comment":"Jim\\nOne extra disc really doesn’t add any extra difficulty. ","userId":"UbhgAjZIuLauV1dw2G4QsocHIk83","displayName":"Georgia Jim","source":"Classification Sheet","createdAt":"2026-10-09T16:10:57.410Z","updatedAt":"2026-10-09T16:10:57.410Z"}]`);export{e as t};